// Pure semantic editor kernel. Host-owned content/rendering/persistence are adapters.
export const canonical=value=>JSON.stringify(value,(_,v)=>v&&typeof v==='object'&&!Array.isArray(v)?Object.fromEntries(Object.keys(v).sort().map(k=>[k,v[k]])):v);
const copy=structuredClone,integer=(v,min,max=100000)=>Number.isInteger(v)&&v>=min&&v<=max,id=v=>typeof v==='string'&&/^[A-Za-z0-9][A-Za-z0-9_.:-]{0,119}$/.test(v),fail=message=>{throw Error(message);};
export const defaultGrid=()=>({columns:24,rowHeight:28,gapX:12,gapY:12,minRows:8,trailingRows:1});
export class BlockRegistry{
 #types=new Map();
 register(definition){if(!id(definition.type)||!integer(definition.version,1,100)||!integer(definition.minCols,1,96)||!integer(definition.minRows,1)||typeof definition.validate!=='function')fail('Invalid block definition.');const key=definition.type+'@'+definition.version;if(this.#types.has(key))fail('Duplicate block definition.');this.#types.set(key,Object.freeze({...definition,capabilities:Object.freeze({...definition.capabilities})}));return this;}
 get(block){return this.#types.get(block.type+'@'+block.version);}
 can(block,action){return !!this.get(block)?.capabilities?.[action]&&block.capabilities?.[action]!==false;}
}
export function validateGrid(g){if(!g||!integer(g.columns,1,96)||!integer(g.minRows,1)||!integer(g.trailingRows,0,100))fail('Invalid grid.');for(const k of ['rowHeight','gapX','gapY'])if(!Number.isFinite(g[k])||g[k]<(k==='rowHeight'?1:0)||g[k]>1000)fail('Invalid grid measurement.');return g;}
export function validatePlacement(p,g){if(!p||!integer(p.col,0)||!integer(p.row,0)||!integer(p.cols,1,g.columns)||!integer(p.rows,1)||!integer(p.z,0)||p.col+p.cols>g.columns||p.row+p.rows>100000||typeof p.visible!=='boolean'||typeof p.locked!=='boolean')fail('Invalid placement.');return p;}
export function validateDocument(doc,registry){
 if(!doc||doc.schemaVersion!==1||!id(doc.id)||!Array.isArray(doc.sections)||doc.sections.length>100||canonical(doc).length>2000000)fail('Invalid editor document.');const ids=new Set([doc.id]);
 for(const s of doc.sections){if(!id(s.id)||ids.has(s.id)||!['layer','reject','push'].includes(s.policy)||!Array.isArray(s.order)||s.order.length>1000||new Set(s.order).size!==s.order.length||!s.blocks||!s.layouts)fail('Invalid section.');ids.add(s.id);if(canonical(Object.keys(s.blocks).sort())!==canonical([...s.order].sort()))fail('Block order mismatch.');
  for(const bid of s.order){const b=s.blocks[bid];if(!id(bid)||ids.has(bid)||b.id!==bid||!id(b.type)||!integer(b.version,1,100)||!b.content||!b.presentation||!b.capabilities)fail('Invalid block.');ids.add(bid);const definition=registry.get(b);if(definition&&!definition.validate(b.content,b.presentation))fail('Invalid block content.');}
  if(!Object.keys(s.layouts).length||Object.keys(s.layouts).length>10)fail('Missing breakpoint.');
  for(const [bp,l] of Object.entries(s.layouts)){if(!id(bp))fail('Invalid breakpoint.');validateGrid(l.grid);if(!integer(l.rows,l.grid.minRows)||canonical(Object.keys(l.placements).sort())!==canonical([...s.order].sort()))fail('Invalid breakpoint layout.');for(const bid of s.order){const entry=l.placements[bid];if(!['manual','generated'].includes(entry.source))fail('Invalid placement provenance.');const p=validatePlacement(entry.value,l.grid),definition=registry.get(s.blocks[bid]);if(p.visible&&p.row+p.rows>l.rows||definition&&(p.cols<definition.minCols||p.rows<definition.minRows))fail('Placement exceeds extent/minimum.');}}
 }
 const walk=(v,depth=0)=>{if(depth>50)fail('Oversized editor metadata.');if(typeof v==='number'&&!Number.isFinite(v))fail('Non-finite editor metadata.');if(v&&typeof v==='object')for(const [k,x] of Object.entries(v)){if(['__proto__','constructor','prototype'].includes(k))fail('Unsafe editor metadata.');walk(x,depth+1);}};walk(doc);return doc;
}
export function intersects(a,b){return a.visible&&b.visible&&a.col<b.col+b.cols&&b.col<a.col+a.cols&&a.row<b.row+b.rows&&b.row<a.row+a.rows;}
export function resolveCollision(original,active,candidate,policy,order){
 if(!['layer','reject','push'].includes(policy)||!original[active])fail('Invalid collision target.');const next=copy(original);next[active]=copy(candidate);const ids=Object.keys(next).filter(x=>x!==active).sort((a,b)=>original[a].row-original[b].row||order.indexOf(a)-order.indexOf(b)||(a<b?-1:1));if(policy==='layer')return next;if(policy==='reject'){if(ids.some(x=>intersects(candidate,next[x])))fail('Occupied placement.');return next;}
 const queue=[active],limit=Math.max(16,ids.length*ids.length*4);let operations=0;
 while(queue.length){const blocker=queue.shift();for(const bid of ids){if(bid===blocker||!intersects(next[blocker],next[bid]))continue;if(next[bid].locked)fail('Locked obstruction.');next[bid].row=next[blocker].row+next[blocker].rows;if(intersects(next[bid],next[active]))next[bid].row=next[active].row+next[active].rows;queue.push(bid);if(++operations>limit)fail('Collision resolution limit.');}}
 return next;
}
export function place(doc,registry,{sectionId,breakpoint,blockId,placement,operation='policy'}){
 validateDocument(doc,registry);const next=copy(doc),s=next.sections.find(s=>s.id===sectionId),l=s?.layouts[breakpoint],b=s?.blocks[blockId],entry=l?.placements[blockId];if(!entry||entry.value.locked||!registry.can(b,'move'))fail('Locked or unsupported target.');if(placement.locked!==entry.value.locked||placement.z!==entry.value.z||placement.visible!==entry.value.visible)fail('Movement cannot change capability/layer/visibility.');if((placement.cols!==entry.value.cols||placement.rows!==entry.value.rows)&&!registry.can(b,'resize'))fail('Resize denied.');validatePlacement(placement,l.grid);const def=registry.get(b);if(placement.cols<def.minCols||placement.rows<def.minRows)fail('Minimum span.');
 const map=Object.fromEntries(Object.entries(l.placements).map(([key,v])=>[key,v.value])),resolved=resolveCollision(map,blockId,placement,operation==='direct'?'layer':s.policy,s.order);for(const [key,p] of Object.entries(resolved)){const changed=canonical(p)!==canonical(map[key]);if(changed&&!registry.can(s.blocks[key],'move'))fail('Unsupported obstruction.');l.placements[key]={value:p,source:changed?'manual':l.placements[key].source};}const end=Math.max(0,...Object.values(resolved).filter(p=>p.visible).map(p=>p.row+p.rows));l.rows=Math.max(l.rows,l.grid.minRows,end+l.grid.trailingRows);return validateDocument(next,registry);
}
export function layer(doc,registry,{sectionId,breakpoint,blockId,z}){const next=copy(doc),s=next.sections.find(s=>s.id===sectionId),entry=s?.layouts[breakpoint]?.placements[blockId];if(!entry||entry.value.locked||!registry.can(s.blocks[blockId],'layer')||!integer(z,0))fail('Layer change denied.');entry.value.z=z;entry.source='manual';return validateDocument(next,registry);}
export function textRows(height,g){validateGrid(g);if(!Number.isFinite(height)||height<0||height>1000000)fail('Invalid intrinsic height.');return Math.max(1,Math.ceil((height+g.gapY-0.001)/(g.rowHeight+g.gapY)));}
export function metrics({width,x=0,y=0,scale=1,grid,columnLines,rowLines}){validateGrid(grid);if(![width,x,y,scale].every(Number.isFinite)||scale<=0||width<=(grid.columns-1)*grid.gapX)fail('Invalid canvas transform.');for(const [lines,minimum] of [[columnLines,grid.columns+1],[rowLines,2]])if(lines&&(!Array.isArray(lines)||lines.length<minimum||lines.length>100001||lines[0]!==0||lines.some((v,i)=>!Number.isFinite(v)||i&&v<=lines[i-1])))fail('Invalid measured grid lines.');return {width,x,y,scale,grid,columnLines:columnLines&&copy(columnLines),rowLines:rowLines&&copy(rowLines),cell:(width-(grid.columns-1)*grid.gapX)/grid.columns};}
const gridLine=(lines,index,pitch)=>!lines?index*pitch:index<lines.length?lines[index]:lines.at(-1)+(index-lines.length+1)*pitch;
const nearestLine=(lines,target,pitch)=>{if(!lines)return Math.round(target/pitch);if(target>=lines.at(-1))return lines.length-1+Math.round((target-lines.at(-1))/pitch);let lo=0,hi=lines.length-1;while(hi-lo>1){const mid=(lo+hi)>>1;if(lines[mid]<=target)lo=mid;else hi=mid;}return target-lines[lo]<lines[hi]-target?lo:hi;};
export function rectangle(p,m){const cx=m.cell+m.grid.gapX,ry=m.grid.rowHeight+m.grid.gapY,x=gridLine(m.columnLines,p.col,cx),y=gridLine(m.rowLines,p.row,ry);return {x:m.x+x,y:m.y+y,width:gridLine(m.columnLines,p.col+p.cols,cx)-x-m.grid.gapX,height:gridLine(m.rowLines,p.row+p.rows,ry)-y-m.grid.gapY};}
const freeze=v=>{if(v&&typeof v==='object'){for(const x of Object.values(v))freeze(x);Object.freeze(v);}return v;};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function gesture(history,registry,{sectionId,breakpoint,blockId,start,pointerId=0,transform,kind='drag',edges='se'}){const s=history.present.sections.find(s=>s.id===sectionId),l=s?.layouts[breakpoint],b=s?.blocks[blockId],p=l?.placements[blockId]?.value;if(!p||p.locked||!registry.can(b,kind==='drag'?'move':'resize')||!['drag','resize'].includes(kind)||kind==='resize'&&!/^(n|s|e|w|ne|nw|se|sw)$/.test(edges))fail('Gesture denied.');if(![start.x,start.y].every(Number.isFinite))fail('Invalid pointer.');return freeze({sectionId,breakpoint,blockId,start:copy(start),pointerId,baseline:copy(history.present),transform:metrics({...transform,grid:l.grid}),origin:copy(p),baseGeneration:history.generation,kind,edges,minCols:registry.get(b).minCols,minRows:registry.get(b).minRows});}
export function previewGesture(session,point){const s=session,m=s.transform,p=s.origin;if(![point.x,point.y].every(Number.isFinite))fail('Invalid pointer.');const cx=m.cell+m.grid.gapX,ry=m.grid.rowHeight+m.grid.gapY,dx=(point.x-s.start.x)/m.scale,dy=(point.y-s.start.y)/m.scale,cOrigin=s.kind==='resize'&&s.edges.includes('e')?p.col+p.cols:p.col,rOrigin=s.kind==='resize'&&s.edges.includes('s')?p.row+p.rows:p.row,dc=nearestLine(m.columnLines,gridLine(m.columnLines,cOrigin,cx)+dx,cx)-cOrigin,dr=nearestLine(m.rowLines,gridLine(m.rowLines,rOrigin,ry)+dy,ry)-rOrigin;if(s.kind==='drag')return {...p,col:clamp(p.col+dc,0,m.grid.columns-p.cols),row:clamp(p.row+dr,0,100000-p.rows)};let left=p.col,right=p.col+p.cols,top=p.row,bottom=p.row+p.rows;if(s.edges.includes('e'))right=clamp(right+dc,left+s.minCols,m.grid.columns);if(s.edges.includes('w'))left=clamp(left+dc,0,right-s.minCols);if(s.edges.includes('s'))bottom=clamp(bottom+dr,top+s.minRows,100000);if(s.edges.includes('n'))top=clamp(top+dr,0,bottom-s.minRows);return {...p,col:left,row:top,cols:right-left,rows:bottom-top};}
export function createHistory(doc,registry,{limit=80}={}){if(!integer(limit,1,200))fail('Invalid history limit.');validateDocument(doc,registry);return {present:copy(doc),generation:0,past:[],future:[],limit};}
export function transact(h,next,registry,{baseGeneration=h.generation,label='Edit',operationId}={}){if(baseGeneration!==h.generation)fail('Stale gesture.');validateDocument(next,registry);if(canonical(h.present)===canonical(next))return h;if(!id(operationId)||typeof label!=='string'||label.length>200)fail('Invalid transaction.');const tx={id:operationId,label,before:copy(h.present),after:copy(next)};return {...h,present:copy(next),generation:h.generation+1,past:[...h.past,tx].slice(-h.limit),future:[]};}
export function commitGesture(h,registry,s,point,operationId){if(s.baseGeneration!==h.generation)fail('Stale gesture.');const next=place(h.present,registry,{...s,operation:'direct',placement:previewGesture(s,point)});return transact(h,next,registry,{baseGeneration:s.baseGeneration,label:s.kind==='drag'?'Move block':'Resize block',operationId});}
export function undo(h){const t=h.past.at(-1);return t?{...h,present:copy(t.before),generation:h.generation+1,past:h.past.slice(0,-1),future:[t,...h.future]}:h;}
export function redo(h){const t=h.future[0];return t?{...h,present:copy(t.after),generation:h.generation+1,past:[...h.past,t],future:h.future.slice(1)}:h;}
export function transition(state,event){if(event.type==='select')return {mode:'selected',id:event.id};if(event.type==='canvas')return {mode:'idle'};if(state.mode==='idle')return state;if(event.type==='escape')return state.mode==='selected'?{mode:'idle'}:{mode:'selected',id:state.id};if(event.type==='finish')return {mode:'selected',id:state.id};if(state.mode==='selected'&&['edit','inspect','drag','resize'].includes(event.type))return {mode:{edit:'editing',inspect:'inspector',drag:'dragging',resize:'resizing'}[event.type],id:state.id};return state;}
